#include <iostream>
#include <string>

int main() {
    std::string text = "Welcome to C++ Programming";
    std::string prefix = text.substr(0, 7); // "Welcome"
    std::string lang = text.substr(11, 3);   // "C++"

    std::cout << "Prefix: " << prefix << "\n";
    std::cout << "Language: " << lang << "\n";

    std::size_t pos = text.find("C++");
    if (pos != std::string::npos) {
        std::cout << "Found C++ at index: " << pos << "\n";
    }

    std::size_t missing = text.find("Python");
    if (missing == std::string::npos) {
        std::cout << "Python not found" << "\n";
    }

    std::string s1 = "Apple";
    std::string s2 = "Banana";
    std::cout << "s1.compare(s2): " << s1.compare(s2) << "\n";
    std::cout << "s1 < s2: " << (s1 < s2) << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <sstream>

int main() {
    // 1. Mutation: insert, replace, erase
    std::string s = "Welcome HTML";
    s.insert(8, "to ");          // "Welcome to HTML"
    s.replace(11, 4, "C++");     // "Welcome to C++"
    std::cout << "Mutated string: " << s << "\n";
    std::cout << "Size: " << s.size() << ", Capacity: " << s.capacity() << "\n";

    s.erase(0, 11);              // Erase "Welcome to " -> "C++"
    std::cout << "After erase: " << s << " (Size: " << s.size() << ", Capacity: " << s.capacity() << ")\n";

    // 2. Conversion and word tokenization via stringstream
    std::stringstream numStream;
    double pi = 3.14159;
    numStream << pi;
    std::string piStr = numStream.str();
    std::cout << "Converted PI: " << piStr << "\n";

    std::string sentence = "C++ Object Oriented Thinking";
    std::stringstream wordStream(sentence);
    std::string token;
    std::cout << "Tokens:\n";
    while (wordStream >> token) {
        std::cout << "- " << token << "\n";
    }
    return 0;
}
